  "prediction_basis_card_ids": ["C01", "C14", "C22", "C05", "C08", "C34", "C72", "C85", "C111", "C98", "C87", "C97"],
  "claims": [
    {
      "claim": "The query is N-butylscopolamine, a permanently charged quaternary ammonium tropane ester; the closest L1 structural class match, umeclidinium (also a quaternary ammonium antimuscarinic), has negligible/low oral bioavailability and ≤12% systemic availability from oral and inhaled radiolabel studies.",
      "card_ids": ["C01", "C14", "C22", "C05"]
    },
    {
      "claim": "The antimuscarinic ester oxybutynin (R-enantiomer) has estimated absolute oral F ~6.7-7%, supporting low F for this ester/antimuscarinic class.",
      "card_ids": ["C08", "C34"]
    },
    {
      "claim": "L3 oral exposure records for quaternary ammonium antimuscarinics show only pg/mL-level plasma concentrations after oral dosing (trospium 60 mg ER Cmax ~1.5-1.9 ng/mL and AUC24 ~23 ng·h/mL; glycopyrronium 2 mg oral Cmax 318 pg/mL; scopolamine 0.5 mg oral AUC0-24 50.77 ng·min/mL), consistent with poor oral absorption.",
      "card_ids": ["C72", "C85", "C111", "C98", "C87", "C97"]
    },
    {
      "claim": "L6 hepatic-clearance records for the closest tropane antimuscarinics show low-to-moderate intrinsic/hepatic clearance (ipratropium HLM CLint <7 µL/min/mg and predicted hepatic CL 9.6-12.4 ml/min/kg; atropine human hepatocyte CLint 2.59 µL/min/10^6 cells), indicating hepatic first-pass is not affirmatively high; this does not contradict the absorption-limited low-F conclusion.",
      "card_ids": ["C230", "C262", "C263", "C252"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C230", "C262", "C263", "C252"]
    }
  ],
  "evidence_gaps": [
    "No query-specific measured oral bioavailability, permeability, solubility, or hepatic clearance data are supplied.",
    "L6 records are for other tropane antimuscarinics (ipratropium/atropine), not N-butylscopolamine; no direct hepatic clearance or metabolic stability measurement for the query is available.",
    "L3 exposure records lack IV comparators, so absolute F cannot be derived from them.",
    "No formulation, dose, or species match for the query is available.",
    "L6 hepatic-clearance records are low-to-moderate and do not establish high first-pass loss; the low-F conclusion rests on absorption/charge and analog oral F evidence.",
    "No direct gut-wall efflux or intestinal metabolism measurement for the query is available."
  ],
  "decision_summary": "Prediction remains low. The query is N-butylscopolamine, a permanently charged quaternary ammonium tropane ester; transferable L1 evidence from umeclidinium (negligible/low oral F, ≤12% systemic availability) and oxybutynin (~7% absolute F) supports F <20%. L3 oral exposure records for quaternary ammonium antimuscarinics show only pg/mL-level plasma concentrations after oral dosing. L6 adds hepatic-clearance records for closest tropane antimuscarinics (ipratropium/atropine) showing low-to-moderate intrinsic/hepatic clearance; these are not direct F measurements and do not affirmatively support F ≥20%, nor do they overturn the absorption-limited low-F conclusion. Confidence remains high."
}

